Imported reference; not locally executed. Subject: c
C · adjacency lists · insertion-and-deletion · L2
Concept: Push a new edge in front of the list: e->next = head[u]; head[u] = e
Misconception: Setting head[u] = e with e->next = NULL adds an edge.
Explanation: The new node must point at the current first node before it becomes the head, otherwise the old list is lost. Pushing in front is O(1); the neighbors then come out newest first. An undirected edge is stored twice, once in each endpoint list, so the total space is O(V + 2E).
Incorrect:
struct BadEdge { int to; struct BadEdge *next; };
void alAddBad(struct BadEdge **head, size_t u, int v) {
  struct BadEdge *e = malloc(sizeof *e);
  e->to = v;
  e->next = NULL;
  free(head[u]);
  head[u] = e;
}
Correct:
int alAdd(AdjList *l, size_t u, size_t v, int directed) {
  if (u >= l->n || v >= l->n) return 0;
  AdjEdge *e = malloc(sizeof *e);
  if (e == NULL) return 0;
  e->to = (int)v;
  e->next = l->head[u];
  l->head[u] = e;
  if (!directed && u != v) {
    AdjEdge *r = malloc(sizeof *r);
    if (r == NULL) return 0;
    r->to = (int)u;
    r->next = l->head[v];
    l->head[v] = r;
  }
  return 1;
}
size_t alDegree(const AdjList *l, size_t u) {
  size_t d = 0;
  if (u >= l->n) return 0;
  for (const AdjEdge *e = l->head[u]; e != NULL; e = e->next) d++;
  return d;
}
Complexity: O(1)

