Imported reference; not locally executed. Subject: c
C · AVL trees · complexity · L2
Concept: An AVL tree's height stays below 1.44 log2(n + 2); a plain BST fed sorted keys has height n
Misconception: Balancing only helps on random input.
Explanation: Rotations keep every balance factor within one, which bounds the height by about 1.44 log2(n + 2) for any insertion order. Inserting 1 to n in order gives height about log2(n) in an AVL tree and exactly n in an unbalanced tree. Search, insert and delete are therefore O(log n) in the worst case.
Incorrect:
typedef struct ANode { int key, h; struct ANode *l, *r; } ANode;
ANode *plainInsertBad(ANode *t, int key) {
  if (t == NULL) return anew(key);
  if (key < t->key) t->l = plainInsertBad(t->l, key);
  else if (key > t->key) t->r = plainInsertBad(t->r, key);
  aupd(t);
  return t;
}
Correct:
typedef struct ANode { int key, h; struct ANode *l, *r; } ANode;
int avlHeight(const ANode *t) { return ah(t); }
int avlValid(const ANode *t, int *height) {
  if (t == NULL) { *height = 0; return 1; }
  int hl, hr;
  if (!avlValid(t->l, &hl) || !avlValid(t->r, &hr)) return 0;
  *height = 1 + (hl > hr ? hl : hr);
  return (hl - hr >= -1 && hl - hr <= 1) && *height == t->h;
}
Complexity: O(log n)

