Imported reference; not locally executed. Subject: c
C · AVL trees · creation · L3
Concept: Rebalance on the way back up: a left-right or right-left case needs a double rotation
Misconception: A single rotation fixes every imbalance.
Explanation: If a node is left-heavy but its left child is right-heavy (LR), a single right rotation leaves the tree just as unbalanced. Rotate the child left first, then rotate the node right; the mirror image handles RL. Insert as in a BST, then recompute the height and rebalance every node on the path back to the root: O(log n).
Incorrect:
typedef struct ANode { int key, h; struct ANode *l, *r; } ANode;
ANode *rebalanceBad(ANode *n) {
  aupd(n);
  int b = abal(n);
  if (b > 1) return rotR(n);
  if (b < -1) return rotL(n);
  return n;
}
ANode *avlInsertBad(ANode *t, int key) {
  if (t == NULL) return anew(key);
  if (key < t->key) t->l = avlInsertBad(t->l, key);
  else if (key > t->key) t->r = avlInsertBad(t->r, key);
  else return t;
  return rebalanceBad(t);
}
Correct:
typedef struct ANode { int key, h; struct ANode *l, *r; } ANode;
ANode *rebalance(ANode *n) {
  aupd(n);
  int b = abal(n);
  if (b > 1) {
    if (abal(n->l) < 0) n->l = rotL(n->l);
    return rotR(n);
  }
  if (b < -1) {
    if (abal(n->r) > 0) n->r = rotR(n->r);
    return rotL(n);
  }
  return n;
}
ANode *avlInsert(ANode *t, int key) {
  if (t == NULL) return anew(key);
  if (key < t->key) t->l = avlInsert(t->l, key);
  else if (key > t->key) t->r = avlInsert(t->r, key);
  else return t;
  return rebalance(t);
}
void avlFree(ANode *t) {
  if (t == NULL) return;
  avlFree(t->l);
  avlFree(t->r);
  free(t);
}
Complexity: O(log n)

