Imported reference; not locally executed. Subject: c
C · binary trees · patterns · L2
Concept: Level order uses a queue; a stack in its place visits the right subtree first and loses the level structure
Misconception: Level-order traversal works with any container of pending nodes.
Explanation: Breadth-first traversal takes the oldest pending node, so the pending nodes must live in a FIFO queue. With a stack the newest node is taken first and the output becomes a depth-first order that visits right children early. Time O(n), space O(width).
Incorrect:
typedef struct TNode { int val; struct TNode *left, *right; } TNode;
size_t levelOrderBad(const TNode *root, int *out, size_t cap) {
  if (root == NULL) return 0;
  const TNode **st = malloc(cap * sizeof *st);
  size_t top = 0, n = 0;
  st[top++] = root;
  while (top > 0 && n < cap) {
    const TNode *t = st[--top];
    out[n++] = t->val;
    if (t->left != NULL && top < cap) st[top++] = t->left;
    if (t->right != NULL && top < cap) st[top++] = t->right;
  }
  free(st);
  return n;
}
Correct:
typedef struct TNode { int val; struct TNode *left, *right; } TNode;
size_t levelOrder(const TNode *root, int *out, size_t cap) {
  if (root == NULL) return 0;
  const TNode **q = malloc(cap * sizeof *q);
  if (q == NULL) return 0;
  size_t head = 0, tail = 0, n = 0;
  q[tail++] = root;
  while (head < tail && n < cap) {
    const TNode *t = q[head++];
    out[n++] = t->val;
    if (t->left != NULL && tail < cap) q[tail++] = t->left;
    if (t->right != NULL && tail < cap) q[tail++] = t->right;
  }
  free(q);
  return n;
}
Complexity: O(n)

