  p->v = v;
  return p->v;
}
Correct:
struct Packed { unsigned v : 3; };
int setChecked(struct Packed *p, unsigned v) {
  if (v > 7u) return 0;
  p->v = v;
  return 1;
}
Complexity: O(1)

