Imported reference; not locally executed. Subject: c
C · binary search trees · insertion-and-deletion · L3
Concept: Deleting a node with two children: replace its key with the smallest key of the right subtree, then delete that node
Misconception: A node with two children can be removed by returning one of its subtrees.
Explanation: A leaf is just removed and a node with one child is replaced by that child. With two children, returning either subtree drops the other. Instead copy the inorder successor (the minimum of the right subtree) into the node and delete the successor, which has at most one child. Free exactly the node that leaves the tree.
Incorrect:
typedef struct BNode { int key; struct BNode *left, *right; } BNode;
BNode *bstRemoveBad(BNode *t, int key) {
  if (t == NULL) return NULL;
  if (key < t->key) t->left = bstRemoveBad(t->left, key);
  else if (key > t->key) t->right = bstRemoveBad(t->right, key);
  else return t->right;
  return t;
}
Correct:
typedef struct BNode { int key; struct BNode *left, *right; } BNode;
BNode *bstDelete(BNode *t, int key) {
  if (t == NULL) return NULL;
  if (key < t->key) {
    t->left = bstDelete(t->left, key);
  } else if (key > t->key) {
    t->right = bstDelete(t->right, key);
  } else {
    if (t->left == NULL) { BNode *r = t->right; free(t); return r; }
    if (t->right == NULL) { BNode *l = t->left; free(t); return l; }
    BNode *m = t->right;
    while (m->left != NULL) m = m->left;
    t->key = m->key;
    t->right = bstDelete(t->right, m->key);
  }
  return t;
}
Complexity: O(h)

