Imported reference; not locally executed. Subject: c
C · binary search trees · creation · L1
Concept: Insert by comparing with the key: smaller goes left, larger goes right, equal is ignored
Misconception: Any insertion position produces a valid search tree.
Explanation: The search-tree invariant is that every key in the left subtree is smaller and every key in the right subtree is larger. Insertion therefore descends by comparison and attaches the new node where a NULL link is found. Always going to one side builds a tree in which lookups fail.
Incorrect:
typedef struct BNode { int key; struct BNode *left, *right; } BNode;
BNode *bstNew(int key) {
  BNode *n = malloc(sizeof *n);
  if (n == NULL) return NULL;
  n->key = key;
  n->left = n->right = NULL;
  return n;
}
BNode *bstInsertBad(BNode *t, int key) {
  if (t == NULL) return bstNew(key);
  t->left = bstInsertBad(t->left, key);
  return t;
}
Correct:
typedef struct BNode { int key; struct BNode *left, *right; } BNode;
BNode *bstNew(int key) {
  BNode *n = malloc(sizeof *n);
  if (n == NULL) return NULL;
  n->key = key;
  n->left = n->right = NULL;
  return n;
}
BNode *bstInsert(BNode *t, int key) {
  if (t == NULL) return bstNew(key);
  if (key < t->key) t->left = bstInsert(t->left, key);
  else if (key > t->key) t->right = bstInsert(t->right, key);
  return t;
}
void bstFree(BNode *t) {
  if (t == NULL) return;
  bstFree(t->left);
  bstFree(t->right);
  free(t);
}
Complexity: O(h)

