Imported reference; not locally executed. Subject: c
C · B-trees and B+ trees · fit-and-alternatives · L3
Concept: A B+ tree keeps all keys in linked leaves, so a range scan follows the leaf chain instead of climbing the tree
Misconception: A range scan can stop at the end of the first leaf.
Explanation: In a B+ tree internal nodes only route; every key lives in a leaf, and the leaves form a linked list in key order. A range query finds the first leaf and then follows next pointers until a key exceeds the upper bound. Stopping after the first leaf returns only part of the range. Databases and file systems use B+ trees for this reason.
Incorrect:
typedef struct Leaf { int n; int keys[4]; struct Leaf *next; } Leaf;
size_t leafRangeBad(const Leaf *lf, int lo, int hi, int *out) {
  size_t m = 0;
  for (int i = 0; i < lf->n; i++) {
    if (lf->keys[i] > hi) return m;
    if (lf->keys[i] >= lo) out[m++] = lf->keys[i];
  }
  return m;
}
Correct:
typedef struct Leaf { int n; int keys[4]; struct Leaf *next; } Leaf;
size_t leafRange(const Leaf *lf, int lo, int hi, int *out) {
  size_t m = 0;
  for (; lf != NULL; lf = lf->next) {
    for (int i = 0; i < lf->n; i++) {
      if (lf->keys[i] > hi) return m;
      if (lf->keys[i] >= lo) out[m++] = lf->keys[i];
    }
  }
  return m;
}
Complexity: O(log n + k)

