C · circular linked lists · patterns · L3
Concept: Josephus problem: a circular list models people eliminated every k-th step
Misconception: Counting k nodes means moving k times from the node you just removed.
Explanation: Starting from the node before the first candidate, advance k - 1 times to land on the predecessor of the k-th node, unlink that node, and repeat until one remains. Advancing k times skips one person too many. The circular list needs no special case when the end is passed.
Incorrect:
typedef struct CNode { int val; struct CNode *next; } CNode;
int josephusBad(int n, int k) {
  CNode *nodes = malloc((size_t)n * sizeof *nodes);
  for (int i = 0; i < n; i++) { nodes[i].val = i + 1; nodes[i].next = &nodes[(i + 1) % n]; }
  CNode *prev = &nodes[n - 1];
  for (int left = n; left > 1; left--) {
    for (int s = 0; s < k; s++) prev = prev->next;
    prev->next = prev->next->next;
  }
  int r = prev->val;
  free(nodes);
  return r;
}
Correct:
typedef struct CNode { int val; struct CNode *next; } CNode;
int josephus(int n, int k) {
  CNode *nodes = malloc((size_t)n * sizeof *nodes);
  if (nodes == NULL) return -1;
  for (int i = 0; i < n; i++) { nodes[i].val = i + 1; nodes[i].next = &nodes[(i + 1) % n]; }
  CNode *prev = &nodes[n - 1];
  for (int left = n; left > 1; left--) {
    for (int s = 1; s < k; s++) prev = prev->next;
    prev->next = prev->next->next;
  }
  int r = prev->val;
  free(nodes);
  return r;
}
Complexity: O(n*k)

