C · circular linked lists · insertion-and-deletion · L3
Concept: Deleting the tail or the only node of a circular list must update the tail pointer
Misconception: Unlinking a node from its predecessor is all deletion needs.
Explanation: If the removed node is the tail, the tail pointer must move to the predecessor, or it dangles. If it is the only node, the list becomes empty and the tail becomes NULL. Find the predecessor by walking from the tail, relink, then free.
Incorrect (undefined behaviour reported by the sanitizer: heap-use-after-free):
typedef struct CNode { int val; struct CNode *next; } CNode;
void cllPopHeadBad(CNode **tail) {
  CNode *head = (*tail)->next;
  (*tail)->next = head->next;
  free(head);
}
Correct:
typedef struct CNode { int val; struct CNode *next; } CNode;
int cllPopHead(CNode **tail) {
  if (*tail == NULL) return 0;
  CNode *head = (*tail)->next;
  if (head == *tail) *tail = NULL; else (*tail)->next = head->next;
  free(head);
  return 1;
}
int cllRemove(CNode **tail, int v) {
  if (*tail == NULL) return 0;
  CNode *prev = *tail;
  do {
    CNode *cur = prev->next;
    if (cur->val == v) {
      if (cur == prev) *tail = NULL;
      else {
        prev->next = cur->next;
        if (cur == *tail) *tail = prev;
      }
      free(cur);
      return 1;
    }
    prev = cur;
  } while (prev != *tail);
  return 0;
}
Complexity: O(n)

