C · circular linked lists · iteration · L2
Concept: Traverse a circular list with a do-while: a while loop on p != head never runs
Misconception: while (p != head) visits every node starting at the head.
Explanation: Starting at the head and stopping when you return to the head means the first test already fails, so the loop body never runs. Use do { ... p = p->next; } while (p != head) after checking for the empty list, or stop at the tail.
Incorrect:
typedef struct CNode { int val; struct CNode *next; } CNode;
int cllSumBad(const CNode *tail) {
  if (tail == NULL) return 0;
  int s = 0;
  const CNode *head = tail->next;
  for (const CNode *p = head; p != head; p = p->next) s += p->val;
  return s;
}
Correct:
typedef struct CNode { int val; struct CNode *next; } CNode;
int cllSum(const CNode *tail) {
  if (tail == NULL) return 0;
  int s = 0;
  const CNode *p = tail->next;
  do {
    s += p->val;
    p = p->next;
  } while (p != tail->next);
  return s;
}
Complexity: O(n)

