Imported reference; not locally executed. Subject: c
C · double-ended queues · insertion-and-deletion · L2
Concept: Push at the front by stepping head back with wraparound: (head + cap - 1) % cap
Misconception: Pushing at the front just decrements head.
Explanation: In a ring-buffer deque head is an unsigned index. When it is 0, head - 1 wraps to the largest size_t value and the write lands far outside the array. Add cap before the modulo so the index wraps to the last slot: (head + cap - 1) % cap. Push at the back uses (head + len) % cap.
Incorrect (undefined behaviour reported by the sanitizer: heap-buffer-overflow):
typedef struct { int *data; size_t head, len, cap; } Deque;
int dequeInitBad(Deque *d, size_t cap) {
  d->data = malloc(cap * sizeof *d->data);
  d->head = d->len = 0;
  d->cap = cap;
  return d->data != NULL;
}
void dequePushFrontBad(Deque *d, int v) {
  d->head--;
  d->data[d->head] = v;
  d->len++;
}
Correct:
typedef struct { int *data; size_t head, len, cap; } Deque;
int dequeInit(Deque *d, size_t cap) {
  d->data = malloc(cap * sizeof *d->data);
  d->head = d->len = 0;
  d->cap = d->data != NULL ? cap : 0;
  return d->data != NULL;
}
int dequePushBack(Deque *d, int v) {
  if (d->len == d->cap) return 0;
  d->data[(d->head + d->len) % d->cap] = v;
  d->len++;
  return 1;
}
int dequePushFront(Deque *d, int v) {
  if (d->len == d->cap) return 0;
  d->head = (d->head + d->cap - 1) % d->cap;
  d->data[d->head] = v;
  d->len++;
  return 1;
}
int dequeAt(const Deque *d, size_t i) { return d->data[(d->head + i) % d->cap]; }
void dequeFree(Deque *d) {
  free(d->data);
  d->data = NULL;
  d->head = d->len = d->cap = 0;
}
Complexity: O(1)

