Imported reference; not locally executed. Subject: c
C · doubly linked lists · insertion-and-deletion · L2
Concept: Insert after a node in the right order: set the new node's links first, then the neighbors'
Misconception: Set pos->next = n first, then n->next = pos->next.
Explanation: Overwriting pos->next before reading it makes the new node point to itself and loses the rest of the list. Fill in n->prev and n->next from pos, then update the next neighbor's prev (or the tail), and only then update pos->next.
Incorrect:
typedef struct DNode { int val; struct DNode *prev, *next; } DNode;
typedef struct { DNode *head, *tail; size_t len; } DList;
void dlLinkAfterBad(DNode *pos, DNode *n) {
  n->prev = pos;
  pos->next = n;
  n->next = pos->next;
}
Correct:
typedef struct DNode { int val; struct DNode *prev, *next; } DNode;
typedef struct { DNode *head, *tail; size_t len; } DList;
int dlInsertAfter(DList *l, DNode *pos, int v) {
  DNode *n = malloc(sizeof *n);
  if (n == NULL) return 0;
  n->val = v;
  n->prev = pos;
  n->next = pos->next;
  if (pos->next != NULL) pos->next->prev = n; else l->tail = n;
  pos->next = n;
  l->len++;
  return 1;
}
Complexity: O(1)

