void dlMoveToFrontBad(DList *l, DNode *n) {
  if (n == l->head) return;
  n->prev->next = n->next;
  if (n->next != NULL) n->next->prev = n->prev;
  n->prev = NULL;
  n->next = l->head;
  l->head->prev = n;
  l->head = n;
}
Correct:
typedef struct DNode { int val; struct DNode *prev, *next; } DNode;
typedef struct { DNode *head, *tail; size_t len; } DList;
void dlMoveToFront(DList *l, DNode *n) {
  if (n == l->head) return;
  n->prev->next = n->next;
  if (n->next != NULL) n->next->prev = n->prev; else l->tail = n->prev;
  n->prev = NULL;
  n->next = l->head;
