Imported reference; not locally executed. Subject: c
C · doubly linked lists · creation · L1
Concept: Appending to a doubly linked list sets both directions: the new node's prev and the old tail's next
Misconception: A new node only needs its predecessor to point to it.
Explanation: Each link exists twice: tail->next points forward and node->prev points back. Skipping the prev assignment leaves the new node unreachable from a backward walk. A list struct with head, tail and length makes push at either end O(1).
Incorrect:
typedef struct DNode { int val; struct DNode *prev, *next; } DNode;
typedef struct { DNode *head, *tail; size_t len; } DList;
int dlPushBackBad(DList *l, int v) {
  DNode *n = malloc(sizeof *n);
  if (n == NULL) return 0;
  n->val = v;
  n->prev = NULL;
  n->next = NULL;
  if (l->tail != NULL) l->tail->next = n; else l->head = n;
  l->tail = n;
  l->len++;
  return 1;
}
Correct:
typedef struct DNode { int val; struct DNode *prev, *next; } DNode;
typedef struct { DNode *head, *tail; size_t len; } DList;
int dlPushBack(DList *l, int v) {
  DNode *n = malloc(sizeof *n);
  if (n == NULL) return 0;
  n->val = v;
  n->prev = l->tail;
  n->next = NULL;
  if (l->tail != NULL) l->tail->next = n; else l->head = n;
  l->tail = n;
  l->len++;
  return 1;
}
int dlSumBack(const DList *l) {
  int s = 0;
  for (const DNode *p = l->tail; p != NULL; p = p->prev) s += p->val;
  return s;
}
void dlFree(DList *l) {
  DNode *p = l->head;
  while (p != NULL) {
    DNode *next = p->next;
    free(p);
    p = next;
  }
  l->head = l->tail = NULL;
  l->len = 0;
}
Complexity: O(1)

