  if (p == NULL) return -1;
  for (size_t i = 0; i < n; i++) p[i] = (int)i;
  elSort(l);
  long long total = 0;
  size_t used = 0;
  for (size_t i = 0; i < l->m && used + 1 < n; i++) {
    int a = root(p, l->e[i].u), b = root(p, l->e[i].v);
    if (a == b) continue;
    p[a] = b;
    total += l->e[i].w;
    used++;
  }
  free(p);
  return used + 1 == n ? total : -1;
}

