    case RED: return "red";
    case GREEN: return "green";
  }
  return "?";
}
Correct:
enum Color { RED, GREEN, BLUE };
const char *colorName(enum Color c) {
  switch (c) {
    case RED: return "red";
    case GREEN: return "green";
    case BLUE: return "blue";
  }
  return "?";
}
Complexity: O(1)

