Imported reference; not locally executed. Subject: c
C · hash sets · patterns · L2
Concept: Detect a duplicate in an unsorted array with a set; comparing neighbors only works after sorting
Misconception: Checking a[i] == a[i + 1] finds duplicates.
Explanation: Neighbor comparison only finds equal values that are next to each other, which is true after sorting. For unsorted input, add each element to a set and stop when an add reports that the value was already present: O(n) average time and O(n) space.
Incorrect:
typedef struct SNode { int key; struct SNode *next; } SNode;
typedef struct { SNode **b; size_t nb, count; } HSet;
uint32_t hashInt(int x) {
  uint32_t h = (uint32_t)x;
  h ^= h >> 16;
  h *= 0x45d9f3bu;
  h ^= h >> 16;
  return h;
}
int hasDuplicateBad(const int *a, size_t n) {
  for (size_t i = 0; i + 1 < n; i++)
    if (a[i] == a[i + 1]) return 1;
  return 0;
}
Correct:
typedef struct SNode { int key; struct SNode *next; } SNode;
typedef struct { SNode **b; size_t nb, count; } HSet;
uint32_t hashInt(int x) {
  uint32_t h = (uint32_t)x;
  h ^= h >> 16;
  h *= 0x45d9f3bu;
  h ^= h >> 16;
  return h;
}
int hasDuplicate(const int *a, size_t n) {
  HSet s;
  if (!hsInit(&s, 2 * n + 1)) return -1;
  int dup = 0;
  for (size_t i = 0; i < n && !dup; i++) {
    for (const SNode *p = s.b[hashInt(a[i]) % s.nb]; p != NULL; p = p->next)
      if (p->key == a[i]) dup = 1;
    if (!dup) hsAddNew(&s, a[i]);
  }
  hsFree(&s);
  return dup;
}
Complexity: O(n) average

