C · hash sets · patterns · L3
Concept: Union and intersection are loops over one set with a membership test on the other
Misconception: The intersection can be built by testing each element against the set it came from.
Explanation: Intersection keeps an element of A only if B contains it, so the membership test must use B. Testing against A keeps everything. Union adds all elements of both sets into a new set, whose add already ignores repeats. Both are O(|A| + |B|) on average.
Incorrect:
typedef struct SNode { int key; struct SNode *next; } SNode;
typedef struct { SNode **b; size_t nb, count; } HSet;
uint32_t hashInt(int x) {
  uint32_t h = (uint32_t)x;
  h ^= h >> 16;
  h *= 0x45d9f3bu;
  h ^= h >> 16;
  return h;
}
int hsIntersectBad(HSet *out, const HSet *a, const HSet *b) {
  (void)b;
  for (size_t i = 0; i < a->nb; i++)
    for (const SNode *n = a->b[i]; n != NULL; n = n->next)
      if (hsContains(a, n->key) && !hsContains(out, n->key)) hsAddNew(out, n->key);
  return 1;
}
Correct:
typedef struct SNode { int key; struct SNode *next; } SNode;
typedef struct { SNode **b; size_t nb, count; } HSet;
uint32_t hashInt(int x) {
  uint32_t h = (uint32_t)x;
  h ^= h >> 16;
  h *= 0x45d9f3bu;
  h ^= h >> 16;
  return h;
}
int hsUnion(HSet *out, const HSet *a, const HSet *b) {
  const HSet *both[2] = { a, b };
  for (int k = 0; k < 2; k++)
    for (size_t i = 0; i < both[k]->nb; i++)
      for (const SNode *n = both[k]->b[i]; n != NULL; n = n->next)
        if (!hsContains(out, n->key) && !hsAddNew(out, n->key)) return 0;
  return 1;
}
int hsIntersect(HSet *out, const HSet *a, const HSet *b) {
  for (size_t i = 0; i < a->nb; i++)
    for (const SNode *n = a->b[i]; n != NULL; n = n->next)
      if (hsContains(b, n->key) && !hsAddNew(out, n->key)) return 0;
  return 1;
}
Complexity: O(|A| + |B|)

