C · hash tables · insertion-and-deletion · L3
Concept: Delete by unlinking the entry from its chain before freeing it
Misconception: Freeing the entry is enough to delete a key.
Explanation: The chain still points at the freed entry, so the next lookup in that bucket reads freed memory. Walk the chain with an Entry ** cursor, replace the link with entry->next, then free the key and the entry. Update the count.
Incorrect (undefined behaviour reported by the sanitizer: heap-use-after-free):
typedef struct Entry { char *key; int val; struct Entry *next; } Entry;
typedef struct { Entry **buckets; size_t nb, count; } Table;
uint32_t hashStr(const char *s) {
  uint32_t h = 5381;
  for (; *s != '\0'; s++) h = h * 33 + (unsigned char)*s;
  return h;
}
int tableDelBad(Table *t, const char *k) {
  Entry *e = t->buckets[hashStr(k) % t->nb];
  for (; e != NULL; e = e->next) {
    if (strcmp(e->key, k) == 0) {
      free(e->key);
      free(e);
      t->count--;
      return 1;
    }
  }
  return 0;
}
Correct:
typedef struct Entry { char *key; int val; struct Entry *next; } Entry;
typedef struct { Entry **buckets; size_t nb, count; } Table;
uint32_t hashStr(const char *s) {
  uint32_t h = 5381;
  for (; *s != '\0'; s++) h = h * 33 + (unsigned char)*s;
  return h;
}
