C · hash tables · insertion-and-deletion · L2
Concept: Look the key up before inserting: a put that always prepends creates duplicate entries
Misconception: Put can always add a new entry at the front of the bucket chain.
Explanation: A hash table maps each key to one value. Put must search the bucket chain first and update the value in place when the key exists. Always prepending leaves several entries for the same key, inflates the count and hides updates. The table should also copy the key so it owns its memory.
Incorrect:
typedef struct Entry { char *key; int val; struct Entry *next; } Entry;
typedef struct { Entry **buckets; size_t nb, count; } Table;
uint32_t hashStr(const char *s) {
  uint32_t h = 5381;
  for (; *s != '\0'; s++) h = h * 33 + (unsigned char)*s;
  return h;
}
int tablePutBad(Table *t, const char *k, int v) {
  Entry *e = malloc(sizeof *e);
  if (e == NULL) return 0;
  size_t n = strlen(k) + 1;
  e->key = malloc(n);
  if (e->key == NULL) { free(e); return 0; }
  memcpy(e->key, k, n);
  e->val = v;
  size_t i = hashStr(k) % t->nb;
  e->next = t->buckets[i];
  t->buckets[i] = e;
  t->count++;
  return 1;
}
Correct:
typedef struct Entry { char *key; int val; struct Entry *next; } Entry;
typedef struct { Entry **buckets; size_t nb, count; } Table;
uint32_t hashStr(const char *s) {
  uint32_t h = 5381;
  for (; *s != '\0'; s++) h = h * 33 + (unsigned char)*s;
  return h;
}
int tableInit(Table *t, size_t nb) {
  t->buckets = calloc(nb, sizeof *t->buckets);
  t->nb = t->buckets != NULL ? nb : 0;
  t->count = 0;
  return t->buckets != NULL;
}
Entry *tableFind(const Table *t, const char *k) {
  for (Entry *e = t->buckets[hashStr(k) % t->nb]; e != NULL; e = e->next)
    if (strcmp(e->key, k) == 0) return e;
  return NULL;
}
int tablePut(Table *t, const char *k, int v) {
  Entry *e = tableFind(t, k);
  if (e != NULL) { e->val = v; return 1; }
  e = malloc(sizeof *e);
  if (e == NULL) return 0;
  size_t n = strlen(k) + 1;
  e->key = malloc(n);
  if (e->key == NULL) { free(e); return 0; }
  memcpy(e->key, k, n);
  e->val = v;
  size_t i = hashStr(k) % t->nb;
  e->next = t->buckets[i];
  t->buckets[i] = e;
  t->count++;
  return 1;
}
int tableGet(const Table *t, const char *k, int *out) {
  Entry *e = tableFind(t, k);
  if (e == NULL) return 0;
  *out = e->val;
  return 1;
}
void tableFree(Table *t) {
  for (size_t i = 0; i < t->nb; i++) {
    Entry *e = t->buckets[i];
    while (e != NULL) {
      Entry *next = e->next;
      free(e->key);
      free(e);
      e = next;
    }
  }
  free(t->buckets);
  t->buckets = NULL;
  t->nb = t->count = 0;
}
Complexity: O(1) average

