Imported reference; not locally executed. Subject: c
C · binary heaps · patterns · L3
Concept: Keep the k largest values in a min-heap of size k; after replacing the root you must sift down
Misconception: Replacing the root of the heap with a larger value keeps it a heap.
Explanation: The k-th largest of n values needs only a min-heap of size k whose root is the smallest of the k largest seen so far. A new value larger than the root replaces it, and the heap property is restored by sifting down. Without that step the root is no longer the minimum. The cost is O(n log k) time and O(k) space.
Incorrect:
int kthLargestBad(const int *a, size_t n, size_t k) {
  int *h = malloc(k * sizeof *h);
  size_t m = 0;
  for (size_t i = 0; i < n; i++) {
    if (m < k) {
      h[m++] = a[i];
      for (size_t j = m - 1; j > 0 && h[(j - 1) / 2] > h[j]; j = (j - 1) / 2) {
        int t = h[j]; h[j] = h[(j - 1) / 2]; h[(j - 1) / 2] = t;
      }
    } else if (a[i] > h[0]) {
      h[0] = a[i];
    }
  }
  int r = h[0];
  free(h);
  return r;
}
Correct:
void hSiftUp(int *a, size_t i) {
  while (i > 0) {
    size_t p = (i - 1) / 2;
    if (a[p] <= a[i]) break;
    int t = a[p]; a[p] = a[i]; a[i] = t;
    i = p;
  }
}
void hSiftDown(int *a, size_t n, size_t i) {
  for (;;) {
    size_t l = 2 * i + 1, r = l + 1, m = i;
    if (l < n && a[l] < a[m]) m = l;
    if (r < n && a[r] < a[m]) m = r;
    if (m == i) break;
    int t = a[m]; a[m] = a[i]; a[i] = t;
    i = m;
  }
}
int kthLargest(const int *a, size_t n, size_t k) {
  if (k == 0 || k > n) return INT_MIN;
  int *h = malloc(k * sizeof *h);
  if (h == NULL) return INT_MIN;
  size_t m = 0;
  for (size_t i = 0; i < n; i++) {
    if (m < k) {
      h[m] = a[i];
      hSiftUp(h, m);
      m++;
    } else if (a[i] > h[0]) {
      h[0] = a[i];
      hSiftDown(h, m, 0);
    }
  }
  int r = h[0];
  free(h);
  return r;
}
Complexity: O(n log k)

