  for (;;) {
    size_t l = 2 * i + 1, r = l + 1, m = i;
    if (l < n && a[l] < a[m]) m = l;
    if (r < n && a[r] < a[m]) m = r;
    if (m == i) break;
    int t = a[m]; a[m] = a[i]; a[i] = t;
    i = m;
  }
}
int heapPop(MinHeap *h, int *out) {
  if (h->n == 0) return 0;
  *out = h->a[0];
  h->a[0] = h->a[--h->n];
  hSiftDown(h->a, h->n, 0);
  return 1;
}

