C · binary heaps · insertion-and-deletion · L2
Concept: Push appends at the end and sifts up, comparing with the parent (i - 1) / 2
Misconception: Sift-up can use i / 2 as the parent.
Explanation: A new element goes to the first free slot, which keeps the tree complete, and then swaps with its parent while it is smaller. With i / 2 as the parent index the wrong ancestor is compared in a 0-based array and the heap property breaks. Sift-up takes O(log n); growing the array by doubling keeps push O(log n) overall.
Incorrect:
void hSiftUpBad(int *a, size_t i) {
  while (i > 0) {
    size_t p = i / 2;
    if (a[p] <= a[i]) break;
    int t = a[p]; a[p] = a[i]; a[i] = t;
    i = p;
  }
}
void pushBad(int *a, size_t *n, int v) {
  a[*n] = v;
  hSiftUpBad(a, *n);
  (*n)++;
}
Correct:
typedef struct { int *a; size_t n, cap; } MinHeap;
void hSiftUp(int *a, size_t i) {
  while (i > 0) {
    size_t p = (i - 1) / 2;
    if (a[p] <= a[i]) break;
    int t = a[p]; a[p] = a[i]; a[i] = t;
    i = p;
  }
}
int heapPush(MinHeap *h, int v) {
  if (h->n == h->cap) {
    size_t nc = h->cap != 0 ? h->cap * 2 : 4;
    int *p = realloc(h->a, nc * sizeof *p);
    if (p == NULL) return 0;
    h->a = p;
    h->cap = nc;
  }
  h->a[h->n] = v;
  hSiftUp(h->a, h->n);
  h->n++;
  return 1;
}
void heapFree(MinHeap *h) {
  free(h->a);
  h->a = NULL;
  h->n = h->cap = 0;
}
Complexity: O(log n)

