Imported reference; not locally executed. Subject: c
C · red-black trees · testing · L2
Concept: A red-black tree needs a black root, no red node with a red child, and the same number of black nodes on every path
Misconception: Forbidding two red nodes in a row is enough to keep the tree balanced.
Explanation: The rules are: the root is black, a red node has only black children, and every path from a node to its NULL links passes the same number of black nodes. Without the black-height rule a long all-black path is allowed. These rules bound the height by 2 log2(n + 1). NULL links count as black.
Incorrect:
typedef struct RNode { int key, red; struct RNode *l, *r; } RNode;
int isRed(const RNode *n) { return n != NULL && n->red; }
int rbValidBad(const RNode *t) {
  if (t == NULL) return 1;
  if (t->red && (isRed(t->l) || isRed(t->r))) return 0;
  return rbValidBad(t->l) && rbValidBad(t->r);
}
Correct:
typedef struct RNode { int key, red; struct RNode *l, *r; } RNode;
int isRed(const RNode *n) { return n != NULL && n->red; }
int rbValid(const RNode *t, int *bh) {
  if (t == NULL) { *bh = 1; return 1; }
  int l, r;
  if (!rbValid(t->l, &l) || !rbValid(t->r, &r)) return 0;
  if (t->red && (isRed(t->l) || isRed(t->r))) return 0;
  if (l != r) return 0;
  *bh = l + (t->red ? 0 : 1);
  return 1;
}
int rbOk(const RNode *t) {
  int bh;
  return !isRed(t) && rbValid(t, &bh);
}
Complexity: O(n)

