C · segment trees · creation · L2
Concept: A recursive segment tree over n leaves needs an array of 4n nodes, not 2n
Misconception: A segment tree over n elements fits in an array of 2n nodes.
Explanation: The node numbering 2i + 1 and 2i + 2 leaves gaps when n is not a power of two, so the largest index used can approach 4n. Allocating 2n works only for bottom-up trees. With 2n slots a recursive build writes past the end of the buffer. Building is O(n) time and O(n) space, with 4n nodes of long long.
Incorrect (undefined behaviour reported by the sanitizer: heap-buffer-overflow):
long long *buildBad(const int *a, size_t n);
static void fillBad(long long *t, const int *a, size_t node, size_t lo, size_t hi) {
  if (lo == hi) { t[node] = a[lo]; return; }
  size_t mid = lo + (hi - lo) / 2;
  fillBad(t, a, 2 * node + 1, lo, mid);
  fillBad(t, a, 2 * node + 2, mid + 1, hi);
  t[node] = t[2 * node + 1] + t[2 * node + 2];
}
long long *buildBad(const int *a, size_t n) {
  long long *t = calloc(2 * n, sizeof *t);
  fillBad(t, a, 0, 0, n - 1);
  return t;
}
Correct:
typedef struct { long long *t; size_t n; } SegTree;
static void segFill(long long *t, const int *a, size_t node, size_t lo, size_t hi) {
  if (lo == hi) { t[node] = a[lo]; return; }
  size_t mid = lo + (hi - lo) / 2;
  segFill(t, a, 2 * node + 1, lo, mid);
  segFill(t, a, 2 * node + 2, mid + 1, hi);
  t[node] = t[2 * node + 1] + t[2 * node + 2];
}
int segInit(SegTree *s, const int *a, size_t n) {
  s->t = NULL; s->n = 0;
  if (n == 0) return 0;
  s->t = calloc(4 * n, sizeof *s->t);
  if (s->t == NULL) return 0;
  s->n = n;
  segFill(s->t, a, 0, 0, n - 1);
  return 1;
}
void segFree(SegTree *s) { free(s->t); s->t = NULL; s->n = 0; }
Complexity: O(n)

