C · segment trees · patterns · L4
Concept: A range-minimum tree returns INT_MAX, the identity of min, for disjoint nodes
Misconception: A disjoint node can return 0 in any segment tree.
Explanation: The value returned for a disjoint node must be the identity of the combine operation: 0 for sum, INT_MAX for min, INT_MIN for max. Returning 0 in a min tree turns every partial overlap into a minimum of 0. Only the combine and the identity change between sum, min and max trees. Query and update stay O(log n).
Incorrect:
static int mrecBad(const int *t, size_t node, size_t lo, size_t hi, size_t l, size_t r) {
  if (r < lo || hi < l) return 0;
  if (l <= lo && hi <= r) return t[node];
  size_t mid = lo + (hi - lo) / 2;
  int x = mrecBad(t, 2 * node + 1, lo, mid, l, r);
  int y = mrecBad(t, 2 * node + 2, mid + 1, hi, l, r);
  return x < y ? x : y;
}
int segMinQueryBad(const int *t, size_t n, size_t l, size_t r) {
  return mrecBad(t, 0, 0, n - 1, l, r);
}
Correct:
typedef struct { int *t; size_t n; } MinSeg;
static void mfill(int *t, const int *a, size_t node, size_t lo, size_t hi) {
  if (lo == hi) { t[node] = a[lo]; return; }
  size_t mid = lo + (hi - lo) / 2;
  mfill(t, a, 2 * node + 1, lo, mid);
  mfill(t, a, 2 * node + 2, mid + 1, hi);
  t[node] = t[2 * node + 1] < t[2 * node + 2] ? t[2 * node + 1] : t[2 * node + 2];
}
int minSegInit(MinSeg *s, const int *a, size_t n) {
  s->t = NULL; s->n = 0;
  if (n == 0) return 0;
  s->t = calloc(4 * n, sizeof *s->t);
  if (s->t == NULL) return 0;
  s->n = n;
  mfill(s->t, a, 0, 0, n - 1);
  return 1;
}
static int mrec(const int *t, size_t node, size_t lo, size_t hi, size_t l, size_t r) {
  if (r < lo || hi < l) return INT_MAX;
  if (l <= lo && hi <= r) return t[node];
  size_t mid = lo + (hi - lo) / 2;
  int x = mrec(t, 2 * node + 1, lo, mid, l, r);
  int y = mrec(t, 2 * node + 2, mid + 1, hi, l, r);
  return x < y ? x : y;
}
int segMinQuery(const MinSeg *s, size_t l, size_t r) {
  if (s->n == 0 || l > r || r >= s->n) return INT_MAX;
  return mrec(s->t, 0, 0, s->n - 1, l, r);
}
void minSegFree(MinSeg *s) { free(s->t); s->t = NULL; s->n = 0; }
Complexity: O(log n)

