static void urec(long long *t, size_t node, size_t lo, size_t hi, size_t i, int v) {
  if (lo == hi) { t[node] = v; return; }
  size_t mid = lo + (hi - lo) / 2;
  if (i <= mid) urec(t, 2 * node + 1, lo, mid, i, v);
  else urec(t, 2 * node + 2, mid + 1, hi, i, v);
  t[node] = t[2 * node + 1] + t[2 * node + 2];
