int balancedBad(const char *s) {
  int d = 0;
  for (; *s != '\0'; s++) {
    if (*s == '(') d++;
    else if (*s == ')') d--;
  }
  return d == 0;
}
Correct:
int balanced(const char *s) {
  size_t top = 0;
  char *st = malloc(strlen(s) + 1);
  if (st == NULL) return 0;
  int ok = 1;
  for (size_t i = 0; s[i] != '\0' && ok; i++) {
    char c = s[i];
    if (c == '(' || c == '[' || c == '{') {
      st[top++] = c;
    } else if (c == ')' || c == ']' || c == '}') {
      char open = c == ')' ? '(' : (c == ']' ? '[' : '{');
      if (top == 0 || st[--top] != open) ok = 0;
    }
  }
  free(st);
  return ok && top == 0;
}
Complexity: O(n)

