C · stacks · transformation · L3
Concept: Evaluate postfix with a stack and pop the right operand first: a - b needs b from the top
Misconception: Pop the operands in order and compute first - second.
Explanation: In postfix notation the right operand is pushed last, so it is on top. Pop b first, then a, and compute a op b. Reversing the order gives the wrong result for the non-commutative operators - and /. Validate underflow, trailing operands and division by zero.
Incorrect:
int rpnEvalBad(const char *s, long *out) {
  long st[64];
  size_t top = 0;
  while (*s != '\0') {
    if (isspace((unsigned char)*s)) { s++; continue; }
    if (isdigit((unsigned char)*s)) {
      char *end;
      if (top == 64) return 0;
      st[top++] = strtol(s, &end, 10);
      s = end;
      continue;
    }
    if (top < 2) return 0;
    long a = st[--top], b = st[--top];
    switch (*s) {
      case '+': st[top++] = a + b; break;
      case '-': st[top++] = a - b; break;
      case '*': st[top++] = a * b; break;
      case '/': if (b == 0) return 0; st[top++] = a / b; break;
      default: return 0;
    }
    s++;
  }
  if (top != 1) return 0;
  *out = st[0];
  return 1;
}
Correct:
int rpnEval(const char *s, long *out) {
  long st[64];
  size_t top = 0;
  while (*s != '\0') {
    if (isspace((unsigned char)*s)) { s++; continue; }
    if (isdigit((unsigned char)*s)) {
      char *end;
      if (top == 64) return 0;
      st[top++] = strtol(s, &end, 10);
      s = end;
      continue;
    }
    if (top < 2) return 0;
    long b = st[--top], a = st[--top];
    switch (*s) {
      case '+': st[top++] = a + b; break;
      case '-': st[top++] = a - b; break;
      case '*': st[top++] = a * b; break;
      case '/': if (b == 0) return 0; st[top++] = a / b; break;
      default: return 0;
    }
    s++;
  }
  if (top != 1) return 0;
  *out = st[0];
  return 1;
}
Complexity: O(n)

