Imported reference; not locally executed. Subject: c
C · tries (prefix trees) · insertion-and-deletion · L3
Concept: Remove a word by clearing its end flag and freeing only the nodes that no other word uses
Misconception: Freeing the last node of the word removes it.
Explanation: The parent still points at a node that was freed, and the node may also be a prefix of other words. Clear the end flag, then on the way back up free a child only if it has no end flag and no children, and set the parent link to NULL. Shared prefixes stay intact.
Incorrect (undefined behaviour reported by the sanitizer: heap-use-after-free):
typedef struct TrieNode { struct TrieNode *next[26]; int end; } TrieNode;
TrieNode *trieNew(void) { return calloc(1, sizeof(TrieNode)); }
void trieRemoveBad(TrieNode *root, const char *w) {
  TrieNode *t = root;
  for (; *w != '\0'; w++) {
    t = t->next[*w - 'a'];
    if (t == NULL) return;
  }
  free(t);
}
Correct:
typedef struct TrieNode { struct TrieNode *next[26]; int end; } TrieNode;
TrieNode *trieNew(void) { return calloc(1, sizeof(TrieNode)); }
int trieRemoveRec(TrieNode *n, const char *w, int *removed) {
  if (*w == '\0') {
    if (n->end) { n->end = 0; *removed = 1; }
  } else if (*w >= 'a' && *w <= 'z' && n->next[*w - 'a'] != NULL) {
    if (trieRemoveRec(n->next[*w - 'a'], w + 1, removed)) {
      free(n->next[*w - 'a']);
      n->next[*w - 'a'] = NULL;
    }
  }
  if (n->end) return 0;
  for (int k = 0; k < 26; k++)
    if (n->next[k] != NULL) return 0;
  return 1;
}
int trieRemove(TrieNode *root, const char *w) {
  int removed = 0;
  trieRemoveRec(root, w, &removed);
  return removed;
}
Complexity: O(len)

