Concept: Encode a packet with SLIP by escaping the END and ESC bytes
Misconception: Only the END byte 0xC0 has to be escaped.
Explanation: SLIP marks the end of a packet with the byte 0xC0 (END). If the data contains 0xC0 it is sent as 0xDB 0xDC, and because 0xDB (ESC) now has a special meaning it too must be escaped, as 0xDB 0xDD. Skipping the ESC rule makes the decoder misread any data byte 0xDB. Check the output capacity before every write.
Incorrect:
int slipBad(const uint8_t *in, size_t n, uint8_t *out) {
  size_t o = 0;
  out[o++] = 0xC0;
  for (size_t i = 0; i < n; i++) {
    if (in[i] == 0xC0) { out[o++] = 0xDB; out[o++] = 0xDC; }
    else out[o++] = in[i];
  }
  out[o++] = 0xC0;
  return (int)o;
}
Correct:
int slipEncode(const uint8_t *in, size_t n, uint8_t *out, size_t cap) {
  size_t o = 0;
  if (cap < 2) return -1;
  out[o++] = 0xC0;
  for (size_t i = 0; i < n; i++) {
    size_t need = (in[i] == 0xC0 || in[i] == 0xDB) ? 2 : 1;
    if (o + need + 1 > cap) return -1;
    if (in[i] == 0xC0) { out[o++] = 0xDB; out[o++] = 0xDC; }
    else if (in[i] == 0xDB) { out[o++] = 0xDB; out[o++] = 0xDD; }
    else out[o++] = in[i];
  }
  out[o++] = 0xC0;
  return (int)o;
}
Complexity: O(n)

