Imported reference; not locally executed. Subject: c; platform: STM32_HAL
Embedded C · STM32_HAL · packet parsing · patterns · Intermediate
Concept: Keep parsing after a bad frame so one corrupt packet does not stop the stream
Misconception: On a checksum failure the receiver should stop and report an error.
Explanation: On a noisy line a corrupt frame is normal. The parser returns to the sync state after every frame, good or bad, and the caller simply continues with the next byte. Stopping at the first failure turns one flipped bit into a dead link. Count the good and the bad frames separately so the error rate can be reported.
Incorrect:
#define PMAX 16
typedef enum { P_SYNC, P_LEN, P_DATA, P_SUM } PState;
typedef struct { PState st; uint8_t len, idx, sum; uint8_t buf[PMAX]; } Parser;
int pktScanBad(const uint8_t *s, size_t n, Parser *p) {
  int good = 0;
  for (size_t i = 0; i < n; i++) {
    int wasSum = (p->st == P_SUM);
    if (pktFeed(p, s[i])) good++;
    else if (wasSum) break;
  }
  return good;
}
Correct:
#define PMAX 16
typedef enum { P_SYNC, P_LEN, P_DATA, P_SUM } PState;
typedef struct { PState st; uint8_t len, idx, sum; uint8_t buf[PMAX]; } Parser;
int pktScan(const uint8_t *s, size_t n, Parser *p) {
  int good = 0;
  for (size_t i = 0; i < n; i++)
    if (pktFeed(p, s[i])) good++;
  return good;
}
Complexity: O(n)

