Embedded C · STM32_HAL · spi master · iteration · Intermediate
Concept: Shift a byte out and in MSB first with the clock idle level and sampling edge of the chosen mode
Misconception: The same bit-bang routine works for all modes if the clock toggles twice per bit.
Explanation: The clock must idle at CPOL. In modes with CPHA 0 the master puts the bit on MOSI before the leading edge and samples MISO on it; in modes with CPHA 1 the master changes MOSI on the leading edge and samples MISO on the trailing edge. Each edge is set by assigning the clock a value, and the byte is shifted most significant bit first. Ignoring CPOL and CPHA works only for the one mode the routine was written for.
Incorrect:
typedef struct { void (*sck)(int); void (*mosi)(int); int (*miso)(void); } SpiPins;
uint8_t xferBad(const SpiPins *p, int mode, uint8_t tx) {
  int cpol = mode & 1, cpha = (mode >> 1) & 1;
  uint8_t rx = 0;
  p->sck(cpol);
  for (int i = 7; i >= 0; i--) {
    if (!cpha) p->mosi((tx >> i) & 1);
    p->sck(!cpol);
    if (cpha) p->mosi((tx >> i) & 1);
    else rx = (uint8_t)((rx << 1) | p->miso());
    p->sck(cpol);
    if (cpha) rx = (uint8_t)((rx << 1) | p->miso());
  }
  return rx;
}
Correct:
typedef struct { void (*sck)(int); void (*mosi)(int); int (*miso)(void); } SpiPins;
uint8_t spiXfer(const SpiPins *p, int mode, uint8_t tx) {
  int cpol = (mode >> 1) & 1, cpha = mode & 1;
  uint8_t rx = 0;
  p->sck(cpol);
  for (int i = 7; i >= 0; i--) {
    if (!cpha) p->mosi((tx >> i) & 1);
    p->sck(!cpol);
    if (cpha) p->mosi((tx >> i) & 1);
    else rx = (uint8_t)((rx << 1) | p->miso());
    p->sck(cpol);
    if (cpha) rx = (uint8_t)((rx << 1) | p->miso());
  }
  return rx;
}
Complexity: O(1)

