from collections import deque

adj = [[1, 2], [3], [3], []]   # adj[u] lists the neighbours of u (directed here)

def bfs_order(adj, s):
    seen, q, out = {s}, deque([s]), []
    while q:
        u = q.popleft()
        out.append(u)
        for v in adj[u]:
            if v not in seen:
                seen.add(v)
                q.append(v)
    return out

