class SinglyList
  include Enumerable
  attr_reader :head, :tail, :size
  def initialize
    @head = @tail = nil
    @size = 0
  end
  def push_front(v)
    node = SLNode.new(v, @head)
    @head = node
    @tail ||= node
    @size += 1
    self
  end
  def push_back(v)
    node = SLNode.new(v)
    if @tail
      @tail.next = node
    else
      @head = node
    end
    @tail = node
    @size += 1
    self
  end
