class Stack
  include Enumerable
  def initialize
    @items = []
  end
  def push(v)
    @items.push(v)
    self
  end
  def pop
    raise EmptyStackError, "pop from empty stack" if @items.empty?
    @items.pop
  end
  def peek
    raise EmptyStackError, "peek at empty stack" if @items.empty?
    @items.last
  end
  def empty?
    @items.empty?
  end
  def size
    @items.size
  end
  def each(&block)
    return to_enum(:each) unless block
    @items.reverse_each(&block)
    self
  end
end

