  data: number[] = [];
  push(x: number): void {
    const d = this.data;
    d.push(x);
    const i = d.length - 1;
    const p = (i - 1) >> 1;
    if (i > 0 && (d[p] as number) > (d[i] as number)) {
      [d[p], d[i]] = [d[i] as number, d[p] as number];
    }
