Correct:
 function siftDown(a: number[], start: number, n: number): void {
  let i = start;
  for (;;) {
    const l = 2 * i + 1;
    const r = l + 1;
    let m = i;
    if (l < n && (a[l] as number) < (a[m] as number)) m = l;
    if (r < n && (a[r] as number) < (a[m] as number)) m = r;
    if (m === i) return;
    [a[i], a[m]] = [a[m] as number, a[i] as number];
    i = m;
  }
}
class MinHeap {
  data: number[] = [];
  get size(): number { return this.data.length; }
  peek(): number | undefined { return this.data[0]; }
  push(x: number): void {
    const d = this.data;
    d.push(x);
    let i = d.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if ((d[p] as number) <= (d[i] as number)) break;
      [d[p], d[i]] = [d[i] as number, d[p] as number];
      i = p;
    }
  }
  pop(): number | undefined {
    const d = this.data;
    if (d.length === 0) return undefined;
    const top = d[0] as number;
    const last = d.pop() as number;
    if (d.length > 0) {
      d[0] = last;
      siftDown(d, 0, d.length);
    }
    return top;
  }
}
