TypeScript · avltree · mutation · L3
Concept: A left-right case needs a rotation of the child first; one rotation leaves it unbalanced
Misconception: Any imbalance of +2 is fixed by one right rotation.
Explanation: When the left child is itself right-heavy (balance factor negative), a single right rotation only moves the problem to the other side. Rotate the left child left first, which turns the case into left-left, then rotate the node right. The mirror case needs a right rotation of the right child, then a left rotation.
Incorrect:
function rebalanceBad<K>(n: AvlNode<K>): AvlNode<K> {
  fix(n);
  const b = hOf(n.left) - hOf(n.right);
  if (b > 1) return rotateRight(n);
  if (b < -1) return rotateLeft(n);
  return n;
}
Correct:
function bf<K>(n: AvlNode<K> | null): number {
  return n === null ? 0 : hOf(n.left) - hOf(n.right);
}
function rebalance<K>(n: AvlNode<K>): AvlNode<K> {
  fix(n);
  const b = bf(n);
  if (b > 1) {
    if (bf(n.left) < 0) n.left = rotateLeft(n.left as AvlNode<K>);
    return rotateRight(n);
  }
  if (b < -1) {
    if (bf(n.right) > 0) n.right = rotateRight(n.right as AvlNode<K>);
    return rotateLeft(n);
  }
  return n;
}
Complexity: O(1)

