TypeScript · avltree · insertion-and-deletion · L3
Concept: Insert must rebalance every ancestor on the way back, not only update heights
Misconception: Updating heights after an insert is enough to keep the tree balanced.
Explanation: Heights only describe the tree. Each ancestor of the new leaf must be checked and rotated when its balance factor reaches 2 in absolute value. Without that, sorted input builds a chain with height n, which removes the logarithmic guarantee.
Incorrect:
function insertBad<K>(n: AvlNode<K> | null, key: K, cmp: Cmp<K>): AvlNode<K> {
  if (n === null) return new AvlNode(key);
  const c = cmp(key, n.key);
  if (c < 0) n.left = insertBad(n.left, key, cmp);
  else if (c > 0) n.right = insertBad(n.right, key, cmp);
  fix(n);
  return n;
}
Correct:
type Cmp<K> = (a: K, b: K) => number;
const numCmp: Cmp<number> = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
function insert<K>(n: AvlNode<K> | null, key: K, cmp: Cmp<K>): AvlNode<K> {
  if (n === null) return new AvlNode(key);
  const c = cmp(key, n.key);
  if (c < 0) n.left = insert(n.left, key, cmp);
  else if (c > 0) n.right = insert(n.right, key, cmp);
  else return n;
  return rebalance(n);
}
function inorder<K>(n: AvlNode<K> | null): K[] {
  return n === null ? [] : [...inorder(n.left), n.key, ...inorder(n.right)];
}
Complexity: O(log n)

