TypeScript · avltree · mutation · L2
Concept: After a rotation, recompute the demoted node first and the new root second
Misconception: After a rotation the two heights can be updated in either order.
Explanation: A node height is computed from its children. After rotateRight the old root y becomes a child of the new root x, so y must be recomputed first. Computing x first reads the stale height of y and stores a wrong height that spreads to every ancestor.
Incorrect:
function rotateRightBad<K>(y: AvlNode<K>): AvlNode<K> {
  const x = y.left as AvlNode<K>;
  y.left = x.right;
  x.right = y;
  fix(x);
  fix(y);
  return x;
}
Correct:
class AvlNode<K> {
  height = 1;
  constructor(
    public key: K,
    public left: AvlNode<K> | null = null,
    public right: AvlNode<K> | null = null,
  ) {}
}
function hOf<K>(n: AvlNode<K> | null): number {
  return n === null ? 0 : n.height;
}
function fix<K>(n: AvlNode<K>): void {
  n.height = 1 + Math.max(hOf(n.left), hOf(n.right));
}
function rotateRight<K>(y: AvlNode<K>): AvlNode<K> {
  const x = y.left as AvlNode<K>;
  y.left = x.right;
  x.right = y;
  fix(y);
  fix(x);
  return x;
}
function rotateLeft<K>(x: AvlNode<K>): AvlNode<K> {
  const y = x.right as AvlNode<K>;
  x.right = y.left;
  y.left = x;
  fix(x);
  fix(y);
  return y;
}
Complexity: O(1)

