Imported reference; not locally executed. Subject: typescript
TypeScript · bloomfilter · creation · L2
Concept: A Bloom filter needs k different bit positions per item; repeating one hash makes k meaningless
Misconception: Calling the same hash function k times gives k probes.
Explanation: Each item sets k bits. If all k positions come from the same hash value they collapse to one bit, so the filter behaves as if k = 1 and its false positive rate is much higher than designed. Derive k positions from two independent hashes: index_i = (h1 + i * h2) mod m, with h2 made odd so that it is never zero.
Incorrect:
function fnv1a(s: string, seed = 0x811c9dc5): number {
  let h = seed >>> 0;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h;
}
function indexes(item: string, m: number, k: number): number[] {
  const h1 = fnv1a(item);
  const h2 = (fnv1a(item, 0x9747b28c) | 1) >>> 0;
  return Array.from({ length: k }, (_, i) => (h1 + i * h2) % m);
}
class BloomOneHash {
  bits: Uint8Array;
  constructor(readonly m: number, readonly k: number) { this.bits = new Uint8Array(m); }
  private idx(item: string): number[] {
    return Array.from({ length: this.k }, () => fnv1a(item) % this.m);
  }
  add(item: string): void { for (const i of this.idx(item)) this.bits[i] = 1; }
  bitsSet(): number { return this.bits.reduce((a, b) => a + b, 0); }
}
Correct:
function fnv1a(s: string, seed = 0x811c9dc5): number {
  let h = seed >>> 0;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return h;
}
function indexes(item: string, m: number, k: number): number[] {
  const h1 = fnv1a(item);
  const h2 = (fnv1a(item, 0x9747b28c) | 1) >>> 0;
  return Array.from({ length: k }, (_, i) => (h1 + i * h2) % m);
}
class BloomFilter {
  bits: Uint8Array;
  constructor(readonly m: number, readonly k: number) { this.bits = new Uint8Array(m); }
  add(item: string): void {
    for (const i of indexes(item, this.m, this.k)) this.bits[i] = 1;
  }
  has(item: string): boolean {
    return indexes(item, this.m, this.k).every((i) => this.bits[i] === 1);
