TypeScript · bst · insertion-and-deletion · L3
Concept: Deleting a node with two children copies the in-order successor and removes it from the right subtree
Misconception: A node with two children can be replaced by its left child.
Explanation: Replacing the node with one child discards the other subtree. Copy the smallest key of the right subtree (the successor) into the node, then remove that key from the right subtree. A node with at most one child is replaced by that child.
Incorrect:
function removeBad<K>(n: BNode<K> | null, key: K, cmp: Cmp<K>): BNode<K> | null {
  if (n === null) return null;
  const c = cmp(key, n.key);
  if (c < 0) n.left = removeBad(n.left, key, cmp);
  else if (c > 0) n.right = removeBad(n.right, key, cmp);
  else return n.left ?? n.right;
  return n;
}
Correct:
function remove<K>(n: BNode<K> | null, key: K, cmp: Cmp<K>): BNode<K> | null {
  if (n === null) return null;
  const c = cmp(key, n.key);
  if (c < 0) n.left = remove(n.left, key, cmp);
  else if (c > 0) n.right = remove(n.right, key, cmp);
  else {
    if (n.left === null) return n.right;
    if (n.right === null) return n.left;
    let succ = n.right;
    while (succ.left !== null) succ = succ.left;
    n.key = succ.key;
    n.right = remove(n.right, succ.key, cmp);
  }
  return n;
}
Complexity: O(h)

