TypeScript · doublylinkedlist · insertion-and-deletion · L2
Concept: Inserting after a node needs four pointer updates; skipping next.prev breaks backward traversal
Misconception: Linking the new node forward is enough for a correct list.
Explanation: Inserting after node n changes four links: new.prev = n, new.next = n.next, n.next.prev = new and n.next = new. Missing n.next.prev leaves the following node pointing back at n, so reversed traversal skips the new value. If n was the tail, the tail pointer must move.
Incorrect:
type DNode<T> = { value: T; prev: DNode<T> | null; next: DNode<T> | null };
type DLike<T> = { head: DNode<T> | null; tail: DNode<T> | null; size: number };
function insertAfterBad<T>(l: DLike<T>, n: DNode<T>, value: T): DNode<T> {
  const node: DNode<T> = { value, prev: n, next: n.next };
  n.next = node;
  if (!node.next) l.tail = node;
  l.size++;
  return node;
}
Correct:
type DNode<T> = { value: T; prev: DNode<T> | null; next: DNode<T> | null };
type DLike<T> = { head: DNode<T> | null; tail: DNode<T> | null; size: number };
function insertAfter<T>(l: DLike<T>, n: DNode<T>, value: T): DNode<T> {
  const node: DNode<T> = { value, prev: n, next: n.next };
  if (n.next) n.next.prev = node;
  else l.tail = node;
  n.next = node;
  l.size++;
  return node;
}
Complexity: O(1)

