Imported reference; not locally executed. Subject: typescript
TypeScript · heap · creation · L3
Concept: Heapify builds a heap in O(n) by sifting down from the last parent to the root
Misconception: Sifting down from index 0 upwards builds a heap.
Explanation: Sift-down assumes both subtrees are already heaps, so it must run on the lowest parents first. Start at the last parent, index (n >> 1) - 1, and move toward 0. Running from 0 upward leaves deeper levels unfixed. The total work is O(n), better than n pushes at O(n log n).
Incorrect:
function siftDown(a: number[], start: number, n: number): void {
  let i = start;
  for (;;) {
    const l = 2 * i + 1;
    const r = l + 1;
    let m = i;
    if (l < n && (a[l] as number) < (a[m] as number)) m = l;
    if (r < n && (a[r] as number) < (a[m] as number)) m = r;
    if (m === i) return;
    [a[i], a[m]] = [a[m] as number, a[i] as number];
    i = m;
  }
}
function heapifyBad(a: number[]): number[] {
  for (let i = 0; i < a.length >> 1; i++) siftDown(a, i, a.length);
  return a;
}
Correct:
function siftDown(a: number[], start: number, n: number): void {
  let i = start;
  for (;;) {
    const l = 2 * i + 1;
    const r = l + 1;
    let m = i;
    if (l < n && (a[l] as number) < (a[m] as number)) m = l;
    if (r < n && (a[r] as number) < (a[m] as number)) m = r;
    if (m === i) return;
    [a[i], a[m]] = [a[m] as number, a[i] as number];
    i = m;
  }
}
function heapify(a: number[]): number[] {
  for (let i = (a.length >> 1) - 1; i >= 0; i--) siftDown(a, i, a.length);
  return a;
}
Complexity: O(n)

