TypeScript · heap · insertion-and-deletion · L2
Concept: Sift-up must keep walking: move the index to the parent after every swap
Misconception: One swap with the parent is enough to restore the heap after a push.
Explanation: The new value may be smaller than several ancestors. After each swap the value sits at the parent index and must be compared with the next parent. Forgetting to update the index stops after one swap and leaves the root wrong. The loop runs at most log n times.
Incorrect:
class MinHeapBad {
  data: number[] = [];
  push(x: number): void {
    const d = this.data;
    d.push(x);
    const i = d.length - 1;
    const p = (i - 1) >> 1;
    if (i > 0 && (d[p] as number) > (d[i] as number)) {
      [d[p], d[i]] = [d[i] as number, d[p] as number];
    }
  }
}
Correct:
function siftDown(a: number[], start: number, n: number): void {
  let i = start;
  for (;;) {
    const l = 2 * i + 1;
    const r = l + 1;
    let m = i;
    if (l < n && (a[l] as number) < (a[m] as number)) m = l;
    if (r < n && (a[r] as number) < (a[m] as number)) m = r;
    if (m === i) return;
    [a[i], a[m]] = [a[m] as number, a[i] as number];
    i = m;
  }
}
class MinHeap {
  data: number[] = [];
  get size(): number { return this.data.length; }
  peek(): number | undefined { return this.data[0]; }
  push(x: number): void {
    const d = this.data;
    d.push(x);
    let i = d.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if ((d[p] as number) <= (d[i] as number)) break;
      [d[p], d[i]] = [d[i] as number, d[p] as number];
      i = p;
    }
  }
  pop(): number | undefined {
    const d = this.data;
    if (d.length === 0) return undefined;
    const top = d[0] as number;
    const last = d.pop() as number;
    if (d.length > 0) {
      d[0] = last;
      siftDown(d, 0, d.length);
    }
    return top;
  }
}
Complexity: O(log n)

