TypeScript · linkedlist · mutation · L2
Concept: Reverse in place by saving next before redirecting the pointer
Misconception: Setting cur.next = prev and then moving to cur.next walks the original list.
Explanation: After cur.next = prev, cur.next no longer points forward, so advancing through it walks backwards and the loop ends after one step. Save next first, redirect, then advance with the saved reference. The three pointers prev, cur and next make the reversal O(n) time and O(1) space.
Incorrect:
type ListNode<T> = { value: T; next: ListNode<T> | null };
function reverseBad<T>(head: ListNode<T> | null): ListNode<T> | null {
  let prev: ListNode<T> | null = null;
  let cur = head;
  while (cur) {
    cur.next = prev;
    prev = cur;
    cur = cur.next;
  }
  return prev;
}
Correct:
type ListNode<T> = { value: T; next: ListNode<T> | null };
function reverse<T>(head: ListNode<T> | null): ListNode<T> | null {
  let prev: ListNode<T> | null = null;
  let cur = head;
  while (cur) {
    const next: ListNode<T> | null = cur.next;
    cur.next = prev;
    prev = cur;
    cur = next;
  }
  return prev;
}
Complexity: O(n)

