TypeScript · priorityqueue · patterns · L3
Concept: Merging k sorted lists pushes the successor of each popped item, or the result is truncated
Misconception: Pushing the first element of every list once is enough to merge them.
Explanation: The heap holds one candidate per list. After popping a value, the next value from the same list becomes the new candidate and must be pushed. Without it the output has only the first elements. Store (value, list index, position) in the heap entries.
Incorrect:
function mergeKBad(lists: number[][]): number[] {
  const q = new PriorityQueue<[number, number, number]>((a, b) => a[0] - b[0]);
  lists.forEach((l, i) => { if (l.length) q.push([l[0] as number, i, 0]); });
  const out: number[] = [];
  for (let e = q.pop(); e; e = q.pop()) out.push(e[0]);
  return out;
}
Correct:
function mergeK(lists: number[][]): number[] {
  const q = new PriorityQueue<[number, number, number]>((a, b) => a[0] - b[0]);
  lists.forEach((l, i) => { if (l.length) q.push([l[0] as number, i, 0]); });
  const out: number[] = [];
  for (let e = q.pop(); e; e = q.pop()) {
    out.push(e[0]);
    const next = (lists[e[1]] as number[])[e[2] + 1];
    if (next !== undefined) q.push([next, e[1], e[2] + 1]);
  }
  return out;
}
Complexity: O(N log k)

