const rBad: Record<"a" | "b", number> = Object.fromEntries([["a", 1], ["b", 2]]);
Correct:
function toRecord(pairs: [string, number][]): Record<"a" | "b", number> {
  const o = Object.fromEntries(pairs);
  return { a: o.a ?? 0, b: o.b ?? 0 };
}
Complexity: O(n)

