function minInclusiveBad(s: MinSeg, l: number, r: number): number {
  return s.query(l, r);
}
Correct:
function minInclusive(s: MinSeg, l: number, r: number): number {
  return s.query(l, r + 1);
}
Complexity: O(log n)

