TypeScript · segmenttree · patterns · L3
Concept: Lazy propagation pushes pending range adds to the children before a query descends
Misconception: A query can read child sums directly after a range add.
Explanation: A range add that covers a node completely updates only that node and stores a pending tag for its children. A later query that descends below this node must push the tag down first, or the children still hold the old sums. Skipping the push gives stale results.
Incorrect:
function queryNoPush(
  t: LazySeg, ql: number, qr: number, node = 1, l = 0, r = t.n - 1,
): number {
  if (qr < l || r < ql) return 0;
  if (ql <= l && r <= qr) return t.sum[node] as number;
  const mid = (l + r) >> 1;
  const left = queryNoPush(t, ql, qr, 2 * node, l, mid);
  return left + queryNoPush(t, ql, qr, 2 * node + 1, mid + 1, r);
}
Correct:
class LazySeg {
  n: number;
  sum: number[];
  lazy: number[];
  constructor(n: number) {
    this.n = n;
    this.sum = new Array<number>(4 * n).fill(0);
    this.lazy = new Array<number>(4 * n).fill(0);
  }
  apply(node: number, l: number, r: number, d: number): void {
    this.sum[node] = (this.sum[node] as number) + d * (r - l + 1);
    this.lazy[node] = (this.lazy[node] as number) + d;
  }
  push(node: number, l: number, r: number): void {
    const d = this.lazy[node] as number;
    if (d === 0) return;
    const mid = (l + r) >> 1;
    this.apply(2 * node, l, mid, d);
    this.apply(2 * node + 1, mid + 1, r, d);
    this.lazy[node] = 0;
  }
  rangeAdd(ql: number, qr: number, d: number, node = 1, l = 0, r = this.n - 1): void {
    if (qr < l || r < ql) return;
    if (ql <= l && r <= qr) { this.apply(node, l, r, d); return; }
    this.push(node, l, r);
    const mid = (l + r) >> 1;
    this.rangeAdd(ql, qr, d, 2 * node, l, mid);
    this.rangeAdd(ql, qr, d, 2 * node + 1, mid + 1, r);
    this.sum[node] = (this.sum[2 * node] as number) + (this.sum[2 * node + 1] as number);
  }
  query(ql: number, qr: number, node = 1, l = 0, r = this.n - 1): number {
    if (qr < l || r < ql) return 0;
    if (ql <= l && r <= qr) return this.sum[node] as number;
    this.push(node, l, r);
    const mid = (l + r) >> 1;
    const left = this.query(ql, qr, 2 * node, l, mid);
    return left + this.query(ql, qr, 2 * node + 1, mid + 1, r);
  }
}
Complexity: O(log n)

