TypeScript · stack · iteration · L2
Concept: Iterative DFS pushes the right child first so the left child is visited first
Misconception: Pushing left then right visits the left subtree first.
Explanation: A stack pops the most recent push first. To visit left before right, push right first and left last. Pushing in reading order reverses the traversal: the preorder becomes root, right subtree, left subtree.
Incorrect:
type TNode = { val: number; left: TNode | null; right: TNode | null };
function preorderBad(root: TNode | null): number[] {
  const out: number[] = [];
  const st: TNode[] = root ? [root] : [];
  while (st.length) {
    const n = st.pop() as TNode;
    out.push(n.val);
    if (n.left) st.push(n.left);
    if (n.right) st.push(n.right);
  }
  return out;
}
Correct:
type TNode = { val: number; left: TNode | null; right: TNode | null };
function preorder(root: TNode | null): number[] {
  const out: number[] = [];
  const st: TNode[] = root ? [root] : [];
  while (st.length) {
    const n = st.pop() as TNode;
    out.push(n.val);
    if (n.right) st.push(n.right);
    if (n.left) st.push(n.left);
  }
  return out;
}
Complexity: O(n)

