TypeScript · undirectedgraph · iteration · L2
Concept: Count a component only for a start vertex that has not been visited yet
Misconception: Every vertex is the start of a new component.
Explanation: The outer loop visits all vertices as possible start points. A vertex already reached by an earlier traversal belongs to a component that was already counted. Skip visited starts before incrementing the counter, otherwise the result is the number of vertices.
Incorrect:
function componentsBad(g: UGraph): number {
  const seen = new Array<boolean>(g.n).fill(false);
  let count = 0;
  for (let s = 0; s < g.n; s++) {
    count++;
    if (seen[s]) continue;
    const stack = [s];
    seen[s] = true;
    while (stack.length > 0) {
      const u = stack.pop() as number;
      for (const v of g.adj[u] as Set<number>) {
        if (!seen[v]) { seen[v] = true; stack.push(v); }
      }
    }
  }
  return count;
}
Correct:
function components(g: UGraph): number {
  const seen = new Array<boolean>(g.n).fill(false);
  let count = 0;
  for (let s = 0; s < g.n; s++) {
    if (seen[s]) continue;
    count++;
    const stack = [s];
    seen[s] = true;
    while (stack.length > 0) {
      const u = stack.pop() as number;
      for (const v of g.adj[u] as Set<number>) {
        if (!seen[v]) { seen[v] = true; stack.push(v); }
      }
    }
  }
  return count;
}
Complexity: O(V + E)

