TypeScript · undirectedgraph · patterns · L3
Concept: Cycle detection must skip the parent, because every edge leads back to where it came from
Misconception: If DFS meets a visited neighbour, there is a cycle.
Explanation: In an undirected graph the edge to the parent is also a visited neighbour. Without ignoring the parent, every edge looks like a cycle. Pass the parent into the recursion and skip it; any other visited neighbour closes a cycle.
Incorrect:
function hasCycleBad(g: UGraph): boolean {
  const seen = new Array<boolean>(g.n).fill(false);
  const dfs = (u: number): boolean => {
    seen[u] = true;
    for (const v of g.adj[u] as Set<number>) {
      if (seen[v] || dfs(v)) return true;
    }
    return false;
  };
  for (let s = 0; s < g.n; s++) if (!seen[s] && dfs(s)) return true;
  return false;
}
Correct:
function hasCycle(g: UGraph): boolean {
  const seen = new Array<boolean>(g.n).fill(false);
  const dfs = (u: number, parent: number): boolean => {
    seen[u] = true;
    for (const v of g.adj[u] as Set<number>) {
      if (v === parent) continue;
      if (seen[v] || dfs(v, u)) return true;
    }
    return false;
  };
  for (let s = 0; s < g.n; s++) if (!seen[s] && dfs(s, -1)) return true;
  return false;
}
Complexity: O(V + E)

