TypeScript · weightedgraph · patterns · L4
Concept: Bellman-Ford needs one extra round to detect a negative cycle
Misconception: V - 1 rounds of relaxation are enough, and the result is always valid.
Explanation: With no negative cycle, V - 1 rounds give the final distances. If a V-th round still improves some distance, a negative cycle is reachable and distances are meaningless. A version that stops after V - 1 rounds and returns the array hides that case.
Incorrect:
function bellmanFordBad(g: WGraph, src: number): number[] | null {
  const dist = new Array<number>(g.n).fill(Infinity);
  dist[src] = 0;
  for (let round = 0; round < g.n - 1; round++) {
    g.adj.forEach((row, u) => {
      for (const [v, w] of row) {
        if ((dist[u] as number) + w < (dist[v] as number)) dist[v] = (dist[u] as number) + w;
      }
    });
  }
  return dist;
}
Correct:
function bellmanFord(g: WGraph, src: number): number[] | null {
  const dist = new Array<number>(g.n).fill(Infinity);
  dist[src] = 0;
  for (let round = 0; round < g.n; round++) {
    let changed = false;
    g.adj.forEach((row, u) => {
      for (const [v, w] of row) {
        if ((dist[u] as number) + w < (dist[v] as number)) {
          dist[v] = (dist[u] as number) + w;
          changed = true;
        }
      }
    });
    if (!changed) return dist;
  }
  return null;
}
Complexity: O(V E)

