TypeScript · weightedgraph · patterns · L3
Concept: Prim keeps the cheapest single edge into the tree; adding path lengths turns it into Dijkstra
Misconception: The key of a vertex is its distance from the start, as in Dijkstra.
Explanation: Prim grows a tree by repeatedly adding the vertex with the cheapest single edge to the tree, so the key is the edge weight alone. Using key[u] + w, the distance from the root, builds the shortest path tree instead and returns a larger total.
Incorrect:
function primBad(g: WGraph): number {
  const key = new Array<number>(g.n).fill(Infinity);
  const inTree = new Array<boolean>(g.n).fill(false);
  key[0] = 0;
  let total = 0;
  for (let step = 0; step < g.n; step++) {
    let u = -1;
    for (let i = 0; i < g.n; i++) {
      if (!inTree[i] && (u === -1 || (key[i] as number) < (key[u] as number))) u = i;
    }
    if (u === -1 || key[u] === Infinity) break;
    inTree[u] = true;
    total += key[u] as number;
    for (const [v, w] of g.adj[u] as Edge[]) {
      const nk = (key[u] as number) + w;
      if (!inTree[v] && nk < (key[v] as number)) key[v] = nk;
    }
  }
  return total;
}
Correct:
function prim(g: WGraph): number {
  const key = new Array<number>(g.n).fill(Infinity);
  const inTree = new Array<boolean>(g.n).fill(false);
  key[0] = 0;
  let total = 0;
  for (let step = 0; step < g.n; step++) {
    let u = -1;
    for (let i = 0; i < g.n; i++) {
      if (!inTree[i] && (u === -1 || (key[i] as number) < (key[u] as number))) u = i;
    }
    if (u === -1 || key[u] === Infinity) break;
    inTree[u] = true;
    total += key[u] as number;
    for (const [v, w] of g.adj[u] as Edge[]) {
      if (!inTree[v] && w < (key[v] as number)) key[v] = w;
    }
  }
  return total;
}
Complexity: O(V^2)

